-- Phase 61: specialized customer journeys compiled to the Phase 50 Automation Center. It is not a second workflow, CRM, campaign, offer or messaging engine.
-- quality: allow-nonconcurrent-index reason=new-empty-quality-tables
alter table public.plans add column if not exists customer_journeys_enabled boolean not null default true,add column if not exists journey_experiments_enabled boolean not null default true,add column if not exists journey_ai_assistant_enabled boolean not null default true,add column if not exists next_best_journey_enabled boolean not null default true,add column if not exists journey_network_scope_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists customer_journeys_enabled boolean not null default true,add column if not exists journey_experiments_enabled boolean not null default true,add column if not exists journey_ai_assistant_enabled boolean not null default true,add column if not exists next_best_journey_enabled boolean not null default true,add column if not exists journey_network_scope_enabled boolean not null default true;

create table public.journey_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{journeys:view}',scope_type text not null default 'store' check(scope_type in('organization','brand','region','store')),scope_id uuid,active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
alter table public.journey_member_permissions add constraint journey_permissions_allowed check(permissions <@ array['journeys:view','journeys:create','journeys:edit','journeys:publish','journeys:pause','journeys:view_analytics','journeys:manage_templates','journeys:manage_experiments','journeys:manual_enroll','journeys:manual_exit','journeys:view_network']);
create unique index journey_permission_scope_idx on public.journey_member_permissions(organization_id,user_id,scope_type,coalesce(scope_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table public.customer_journeys(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null check(length(btrim(name)) between 2 and 160),description text,objective text not null check(objective in('activation','repeat_purchase','retention','reactivation','loyalty','recovery','subscription','engagement','cross_sell','upsell','win_back')),objective_label text,status text not null default 'draft' check(status in('draft','review','active','paused','archived','error')),scope_type text not null default 'store' check(scope_type in('organization','brand','region','store')),scope_id uuid,owner_user_id uuid references auth.users(id),priority integer not null default 50 check(priority between 1 and 100),active_version integer,active_version_id uuid,draft_version_id uuid,entry_policy text not null default 'future_events' check(entry_policy in('future_events','currently_eligible_previewed')),reentry_policy text not null default 'never' check(reentry_policy in('never','after_completion','after_cooldown','unlimited_with_cooldown')),cooldown_days integer check(cooldown_days between 1 and 3650),version_migration_policy text not null default 'finish_current_version' check(version_migration_policy in('finish_current_version','migrate_at_safe_point','force_migrate')),mutual_exclusion_group text,workflow_id uuid references public.automation_workflows(id) on delete restrict,global_frequency_cap jsonb not null default '{"messages":2,"days":7}',journey_frequency_cap jsonb not null default '{"messages":2,"days":7}',channel_caps jsonb not null default '{}',send_window jsonb not null default '{"start":"09:00","end":"20:00","timezone":"store"}',created_by uuid not null references auth.users(id),published_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,paused_at timestamptz,archived_at timestamptz,unique(organization_id,name),check(reentry_policy='never' or cooldown_days is not null));
create table public.customer_journey_versions(id uuid primary key default gen_random_uuid(),journey_id uuid not null references public.customer_journeys(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,version integer not null check(version>0),status text not null default 'draft' check(status in('draft','validated','review','published','superseded','rejected')),definition jsonb not null,definition_hash text not null,validation_result jsonb not null default '{}',compiled_workflow_version_id uuid references public.automation_workflow_versions(id) on delete restrict,change_summary text not null default 'Versão inicial',created_by uuid not null references auth.users(id),validated_at timestamptz,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),unique(journey_id,version),unique(journey_id,definition_hash));
alter table public.customer_journeys add constraint customer_journey_active_version_fk foreign key(active_version_id) references public.customer_journey_versions(id) on delete set null;
alter table public.customer_journeys add constraint customer_journey_draft_version_fk foreign key(draft_version_id) references public.customer_journey_versions(id) on delete set null;
create table public.journey_entry_triggers(id uuid primary key default gen_random_uuid(),journey_version_id uuid not null references public.customer_journey_versions(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,event_name text not null,event_schema_version integer not null default 1,trigger_config jsonb not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),foreign key(event_name,event_schema_version) references public.automation_event_registry(event_name,schema_version));
create table public.journey_entry_rules(id uuid primary key default gen_random_uuid(),journey_version_id uuid not null references public.customer_journey_versions(id) on delete cascade,rule_group jsonb not null,rule_order integer not null default 0,created_at timestamptz not null default now(),check(not(rule_group ? 'sql')),check(not(rule_group ? 'javascript')));
create table public.journey_stages(id uuid primary key default gen_random_uuid(),journey_version_id uuid not null references public.customer_journey_versions(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,stage_key text not null,stage_type text not null check(stage_type in('message','wait','condition','branch','offer','task','survey','loyalty_action','exit')),name text not null,config jsonb not null default '{}',position jsonb not null default '{}',automation_node_id uuid references public.automation_nodes(id) on delete restrict,created_at timestamptz not null default now(),unique(journey_version_id,stage_key),check(not(config ? 'sql')),check(not(config ? 'javascript')),check(not(config ? 'url')));
create table public.journey_stage_edges(id uuid primary key default gen_random_uuid(),journey_version_id uuid not null references public.customer_journey_versions(id) on delete cascade,source_stage_id uuid not null references public.journey_stages(id) on delete cascade,target_stage_id uuid not null references public.journey_stages(id) on delete cascade,branch_key text not null default 'next',created_at timestamptz not null default now(),unique(journey_version_id,source_stage_id,target_stage_id,branch_key),check(source_stage_id<>target_stage_id));

create table public.customer_journey_enrollments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,journey_id uuid not null references public.customer_journeys(id) on delete restrict,journey_version_id uuid not null references public.customer_journey_versions(id) on delete restrict,journey_version integer not null,customer_id uuid not null references public.customers(id) on delete restrict,status text not null default 'active' check(status in('active','waiting','paused','completed','exited','suppressed','failed')),entry_event_id text,entry_key text not null,current_stage_id uuid references public.journey_stages(id) on delete set null,automation_execution_id uuid references public.automation_executions(id) on delete set null,experiment_assignment_id uuid,entered_at timestamptz not null default now(),last_action_at timestamptz,next_action_at timestamptz,exited_at timestamptz,exit_reason text,context_snapshot jsonb not null default '{}',attribution_context jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,entry_key));
create unique index journey_one_active_customer_idx on public.customer_journey_enrollments(journey_id,customer_id) where status in('active','waiting','paused');
create index journey_enrollment_worker_idx on public.customer_journey_enrollments(organization_id,status,next_action_at) where status in('active','waiting');
create table public.journey_stage_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,enrollment_id uuid not null references public.customer_journey_enrollments(id) on delete cascade,stage_id uuid references public.journey_stages(id) on delete set null,event_type text not null check(event_type in('entered','waiting','condition_evaluated','branch_selected','action_requested','action_completed','action_failed','timeout','completed','exited','suppressed','corrected')),event_time timestamptz not null default now(),source_type text not null,source_id text,summary text not null,metadata_redacted jsonb not null default '{}',idempotency_key text not null,corrects_event_id bigint references public.journey_stage_events(id),unique(organization_id,idempotency_key));
create table public.journey_event_waits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,enrollment_id uuid not null references public.customer_journey_enrollments(id) on delete cascade,stage_id uuid not null references public.journey_stages(id) on delete restrict,event_name text not null,timeout_at timestamptz not null,timeout_stage_id uuid not null references public.journey_stages(id) on delete restrict,status text not null default 'waiting' check(status in('waiting','matched','timed_out','cancelled')),automation_delay_id uuid references public.automation_delays(id) on delete set null,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.journey_action_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,enrollment_id uuid not null references public.customer_journey_enrollments(id) on delete cascade,stage_id uuid not null references public.journey_stages(id) on delete restrict,action_type text not null check(action_type in('send_message','issue_offer','add_tag','remove_tag','create_task','request_feedback','loyalty_action','exit_journey')),status text not null default 'pending' check(status in('pending','routed','completed','failed','skipped','expired')),destination_registry text not null,automation_step_id uuid references public.automation_execution_steps(id) on delete set null,idempotency_key text not null,expires_at timestamptz,input_redacted jsonb not null default '{}',result_redacted jsonb,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create table public.journey_suppressions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,journey_id uuid references public.customer_journeys(id) on delete cascade,enrollment_id uuid references public.customer_journey_enrollments(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,reason text not null check(reason in('opt_out','no_consent','open_complaint','frequency_cap','quiet_hours','legal_policy','store_closed','unavailable_offer','active_recovery','customer_deleted','duplicate_enrollment','capacity_limit','stock_unavailable','conflicting_journey')),channel text,stage_id uuid references public.journey_stages(id) on delete set null,details_redacted jsonb not null default '{}',suppressed_at timestamptz not null default now(),expires_at timestamptz,resolved_at timestamptz);
create index journey_suppression_analytics_idx on public.journey_suppressions(organization_id,reason,suppressed_at desc);
create table public.journey_frequency_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,journey_id uuid references public.customer_journeys(id) on delete cascade,channel text not null,event_type text not null check(event_type in('sent','delivered','read','clicked','responded','unsubscribed','complaint')),occurred_at timestamptz not null default now(),source_type text not null,source_id text not null,unique(organization_id,source_type,source_id,event_type));

create table public.journey_experiments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,journey_id uuid not null references public.customer_journeys(id) on delete cascade,journey_version_id uuid not null references public.customer_journey_versions(id) on delete cascade,name text not null,test_type text not null check(test_type in('message','delay','offer','channel','subject')),status text not null default 'draft' check(status in('draft','active','paused','completed','cancelled')),variants jsonb not null,control_percent numeric(5,2) not null default 10 check(control_percent between 0 and 50),assignment_salt text not null default gen_random_uuid()::text,minimum_sample_size integer not null default 100 check(minimum_sample_size>=10),starts_at timestamptz,ends_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.journey_experiment_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,experiment_id uuid not null references public.journey_experiments(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,variant_key text not null,is_control boolean not null default false,assignment_hash text not null,assigned_at timestamptz not null default now(),unique(experiment_id,customer_id));
alter table public.customer_journey_enrollments add constraint journey_enrollment_experiment_assignment_fk foreign key(experiment_assignment_id) references public.journey_experiment_assignments(id) on delete set null;
create table public.journey_conversions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,journey_id uuid not null references public.customer_journeys(id) on delete cascade,enrollment_id uuid not null references public.customer_journey_enrollments(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,conversion_type text not null,source_event_id text not null,order_id uuid references public.orders(id) on delete set null,attribution_model text not null check(attribution_model in('first_touch','last_touch','configured','control_comparison')),attributed_revenue_cents bigint,attributed_margin_cents bigint,incremental_lift numeric,incrementality_valid boolean not null default false,converted_at timestamptz not null,unique(organization_id,source_event_id,conversion_type));
create table public.journey_simulations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,journey_version_id uuid not null references public.customer_journey_versions(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,mode text not null check(mode in('sample','historical','backfill_preview')),period_start timestamptz,period_end timestamptz,audience_definition jsonb not null default '{}',eligible_count bigint not null default 0,suppressed_count bigint not null default 0,suppression_reasons jsonb not null default '{}',estimated_actions bigint not null default 0,estimated_messaging_cost_cents bigint,maximum_offer_cost_cents bigint,conflicts jsonb not null default '{}',result jsonb not null default '{}',actions_executed boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.journey_templates(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,name text not null,objective text not null,description text not null,definition jsonb not null,required_features text[] not null default '{}',system_template boolean not null default false,active boolean not null default true,version integer not null default 1,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.journey_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,journey_id uuid references public.customer_journeys(id) on delete cascade,enrollment_id uuid references public.customer_journey_enrollments(id) on delete cascade,job_type text not null check(job_type in('process_event','enroll','progress','resume_wait','expire_action','simulation','backfill')),payload_redacted jsonb not null default '{}',priority integer not null default 50 check(priority between 1 and 100),status text not null default 'pending' check(status in('pending','leased','completed','failed','dead_lettered','cancelled')),available_at timestamptz not null default now(),leased_until timestamptz,attempts integer not null default 0,max_attempts integer not null default 5,idempotency_key text not null,last_error text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create or replace function public.claim_customer_journey_jobs(requested_limit integer default 25) returns setof public.journey_jobs language sql security definer set search_path='' as $$ update public.journey_jobs set status='leased',leased_until=now()+interval '60 seconds',attempts=attempts+1 where id in(select id from public.journey_jobs where status='pending' and available_at<=now() order by priority desc,available_at limit least(greatest(requested_limit,1),100) for update skip locked) returning * $$;
revoke all on function public.claim_customer_journey_jobs(integer) from public,anon,authenticated;grant execute on function public.claim_customer_journey_jobs(integer) to service_role;
create or replace function private.enqueue_customer_journey_event() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.journey_jobs(organization_id,journey_id,job_type,payload_redacted,idempotency_key) select new.organization_id,j.id,'process_event',jsonb_build_object('event_id',new.id,'event_name',new.event_name,'store_id',new.store_id,'customer_id',coalesce(new.payload#>>'{customer,id}',new.payload->>'customer_id'),'received_at',new.received_at),'journey-event:'||j.id::text||':'||new.id from public.customer_journeys j join public.customer_journey_versions v on v.id=j.active_version_id join public.journey_entry_triggers t on t.journey_version_id=v.id and t.event_name=new.event_name and t.event_schema_version=new.schema_version where j.organization_id=new.organization_id and j.status='active' and (j.scope_type<>'store' or j.scope_id=new.store_id) on conflict(organization_id,idempotency_key) do nothing;return new;end $$;
create trigger customer_journey_event_ingest after insert on public.automation_event_inbox for each row execute function private.enqueue_customer_journey_event();
create table public.journey_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,journey_id uuid references public.customer_journeys(id) on delete set null,enrollment_id uuid references public.customer_journey_enrollments(id) on delete set null,actor_user_id uuid references auth.users(id),event_type text not null,reason text,before_state jsonb,after_state jsonb,metadata_redacted jsonb not null default '{}',correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
create index customer_journey_scope_status_idx on public.customer_journeys(organization_id,scope_type,scope_id,status,updated_at desc);
create index journey_versions_journey_version_idx on public.customer_journey_versions(journey_id,version desc);
create index journey_stages_version_idx on public.journey_stages(journey_version_id,created_at);
create index journey_enrollments_customer_idx on public.customer_journey_enrollments(organization_id,customer_id,status,entered_at desc);
create index journey_jobs_claim_idx on public.journey_jobs(status,priority desc,available_at) where status='pending';
create index journey_experiment_customer_idx on public.journey_experiment_assignments(experiment_id,customer_id);
create index journey_conversions_journey_time_idx on public.journey_conversions(organization_id,journey_id,converted_at desc);
create index journey_audit_journey_time_idx on public.journey_audit_events(organization_id,journey_id,created_at desc);

