create table public.fact_journey_enrollments(organization_id uuid not null,journey_id uuid not null,store_id uuid,customer_id uuid not null,enrollment_id uuid not null,status text not null,entered_at timestamptz not null,exited_at timestamptz,data_as_of timestamptz not null,primary key(organization_id,enrollment_id));
create table public.fact_journey_stage_transitions(organization_id uuid not null,journey_id uuid not null,enrollment_id uuid not null,stage_id uuid,event_type text not null,event_time timestamptz not null,data_as_of timestamptz not null,primary key(organization_id,enrollment_id,event_time,event_type));
create table public.fact_journey_actions(organization_id uuid not null,journey_id uuid not null,enrollment_id uuid not null,action_type text not null,status text not null,occurred_at timestamptz not null,data_as_of timestamptz not null,primary key(organization_id,enrollment_id,action_type,occurred_at));
create table public.fact_journey_conversions(organization_id uuid not null,journey_id uuid not null,enrollment_id uuid not null,conversion_type text not null,attributed_revenue_cents bigint,attributed_margin_cents bigint,incremental_lift numeric,incrementality_valid boolean not null,converted_at timestamptz not null,data_as_of timestamptz not null,primary key(organization_id,enrollment_id,conversion_type));
create table public.fact_journey_suppressions(organization_id uuid not null,journey_id uuid,store_id uuid,customer_id uuid not null,reason text not null,suppressed_at timestamptz not null,data_as_of timestamptz not null,primary key(organization_id,customer_id,reason,suppressed_at));
create table public.fact_journey_experiments(organization_id uuid not null,experiment_id uuid not null,variant_key text not null,is_control boolean not null,sample_size bigint not null,conversions bigint not null,attributed_revenue_cents bigint,observed_difference numeric,statistically_valid boolean not null default false,data_as_of timestamptz not null,primary key(organization_id,experiment_id,variant_key));
create table public.dim_journey(id uuid primary key,name text not null,objective text not null);create table public.dim_journey_stage(id uuid primary key,journey_id uuid not null,stage_key text not null,name text not null,stage_type text not null);create table public.dim_journey_objective(code text primary key,label text not null);create table public.dim_suppression_reason(code text primary key,label text not null);create table public.dim_experiment_variant(experiment_id uuid not null,variant_key text not null,label text not null,is_control boolean not null,primary key(experiment_id,variant_key));
insert into public.dim_journey_objective values('activation','Ativação'),('repeat_purchase','Recompra'),('retention','Retenção'),('reactivation','Reativação'),('loyalty','Fidelidade'),('recovery','Recuperação'),('subscription','Assinatura'),('engagement','Engajamento'),('cross_sell','Cross-sell'),('upsell','Upsell'),('win_back','Win-back') on conflict do nothing;
insert into public.dim_suppression_reason select x,initcap(replace(x,'_',' ')) from unnest(array['opt_out','no_consent','open_complaint','frequency_cap','quiet_hours','legal_policy','store_closed','unavailable_offer','active_recovery','customer_deleted','duplicate_enrollment','capacity_limit','stock_unavailable','conflicting_journey']) x on conflict do nothing;

insert into public.report_dataset_registry(id,name,description,source,available_metrics,available_dimensions,available_filters,supported_time_granularity,required_permissions,realtime_or_analytical,sensitivity,column_policy) values
('customer_journey_enrollments','Journey Enrollments','Matrículas e status sem conteúdo de mensagem.','hybrid','{journey_enrollment_count,journey_completion_rate,average_journey_duration}','{date,store,journey,objective,status}','{period,store,journey,objective,status}','{day,week,month}','{reports:view,journeys:view_analytics}','hybrid','restricted','{"customer_id":"restricted"}'),('journey_stage_events','Journey Stage Events','Transições por etapa.','warehouse','{journey_completion_rate,journey_conversion_rate}','{date,store,journey,stage}','{period,store,journey,stage}','{day,week,month}','{reports:view,journeys:view_analytics}','analytical','restricted','{}'),('journey_conversions','Journey Conversions','Conversão e atribuição; causalidade somente com controle válido.','warehouse','{journey_conversion_rate,reactivation_rate,repeat_purchase_conversion,attributed_revenue,attributed_margin,incremental_lift}','{date,store,journey,objective,variant}','{period,store,journey,objective,variant}','{day,week,month}','{reports:view,journeys:view_analytics}','analytical','financial','{}'),('journey_suppressions','Journey Suppressions','Supressões por motivo, não falhas.','warehouse','{journey_suppression_rate,journey_unsubscribe_rate}','{date,store,journey,suppression_reason}','{period,store,journey,suppression_reason}','{day,week,month}','{reports:view,journeys:view_analytics}','analytical','restricted','{}'),('journey_experiments','Journey Experiments','Resultados observados por variante e controle.','warehouse','{journey_conversion_rate,incremental_lift}','{date,journey,experiment,variant}','{period,journey,experiment,variant}','{day,week,month}','{reports:view,journeys:manage_experiments}','analytical','restricted','{}') on conflict(id) do update set updated_at=now();
alter table public.analytics_metric_catalog drop constraint if exists analytics_metric_catalog_evidence_class_check;
alter table public.analytics_metric_catalog add constraint analytics_metric_catalog_evidence_class_check check(evidence_class in('fact','calculation','estimate','attribution','incrementality'));
insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,sensitive,allowed_dimensions) values
('journey_enrollment_count','Journey Enrollment Count','Matrículas únicas.','count distinct enrollment_id','fact_journey_enrollments','jornada/período','CRM','hourly','count','calculation',false,'{date,store,journey,objective}'),('journey_completion_rate','Journey Completion Rate','Concluídas sobre entradas elegíveis.','completed/enrolled','fact_journey_enrollments','jornada/período','CRM','hourly','percent','calculation',false,'{date,store,journey}'),('journey_conversion_rate','Journey Conversion Rate','Conversões observadas sobre matrículas.','converted/enrolled','fact_journey_conversions','jornada/período','CRM','hourly','percent','attribution',false,'{date,store,journey,variant}'),('reactivation_rate','Reactivation Rate','Clientes inativos com nova compra sobre elegíveis.','reactivated/eligible','fact_journey_conversions','jornada/período','CRM','daily','percent','attribution',false,'{date,store,journey}'),('repeat_purchase_conversion','Repeat Purchase Conversion','Segunda compra observada sobre clientes de uma compra.','second_purchase/eligible','fact_journey_conversions','jornada/período','CRM','daily','percent','attribution',false,'{date,store,journey}'),('journey_suppression_rate','Journey Suppression Rate','Supressões sobre ações avaliadas.','suppressed/evaluated','fact_journey_suppressions','jornada/período','CRM','hourly','percent','calculation',false,'{date,store,journey,suppression_reason}'),('journey_unsubscribe_rate','Journey Unsubscribe Rate','Descadastros após contato sobre entregas.','unsubscribed/delivered','journey_frequency_events','jornada/período','CRM','daily','percent','calculation',true,'{date,store,journey,channel}'),('attributed_revenue','Attributed Revenue','Receita atribuída; não prova causalidade.','sum attributed_revenue_cents','fact_journey_conversions','jornada/período','Marketing','daily','cents','attribution',true,'{date,store,journey,variant}'),('attributed_margin','Attributed Margin','Margem atribuída quando custo conhecido.','sum attributed_margin_cents','fact_journey_conversions','jornada/período','Marketing','daily','cents','attribution',true,'{date,store,journey,variant}'),('incremental_lift','Incremental Lift','Diferença treatment-control somente com experimento válido.','treatment-control','fact_journey_experiments','experimento','Data','daily','percent','incrementality',true,'{date,journey,variant}'),('average_journey_duration','Average Journey Duration','Tempo médio entre entrada e saída.','avg exited_at-entered_at','fact_journey_enrollments','jornada/período','CRM','daily','seconds','calculation',false,'{date,store,journey}') on conflict(metric_key) do update set updated_at=now();
insert into public.report_templates(name,description,category,dataset_id,definition_json,system_template,read_only,required_permissions,widget_compatible) values('Performance de Jornadas','Conclusão, conversão atribuída e duração.','customer','customer_journey_enrollments','{"type":"summary"}',true,true,'{reports:view,journeys:view_analytics}',true),('Reativação','Resultados atribuídos de reativação.','customer','journey_conversions','{"type":"trend","filter":{"objective":"reactivation"}}',true,true,'{reports:view,journeys:view_analytics}',true),('Conversão por Etapa','Funnel por estágio.','customer','journey_stage_events','{"type":"grouped_table","groupBy":["stage"]}',true,true,'{reports:view,journeys:view_analytics}',true),('Suppression Reasons','Supressões por motivo.','customer','journey_suppressions','{"type":"grouped_table","groupBy":["suppression_reason"]}',true,true,'{reports:view,journeys:view_analytics}',true),('Jornada por Loja','Comparação por unidade.','customer','customer_journey_enrollments','{"type":"grouped_table","groupBy":["store","journey"]}',true,true,'{reports:view,journeys:view_network}',true),('A/B Journey Results','Diferenças observadas e tamanho de amostra.','customer','journey_experiments','{"type":"table","disclaimer":"Não declarar vencedor sem amostra suficiente."}',true,true,'{reports:view,journeys:manage_experiments}',false);
alter table public.search_documents drop constraint if exists search_documents_entity_type_check;alter table public.search_documents add constraint search_documents_entity_type_check check(entity_type in('order','customer','product','category','table','tab','reservation','delivery','driver','employee','supplier','purchase_order','inventory_item','lot','asset','maintenance_work_order','contract','document','support_ticket','internal_project','internal_task','sales_opportunity','organization','store','campaign','workflow','configuration','report','user','operational_incident','customer360_profile','customer_journey'));
insert into public.search_command_registry(id,title,description,keywords,command_type,route,action_type,required_permission,risk_level,scope,position) values('view-active-journeys','Ver jornadas ativas','Abrir jornadas em execução','{jornadas,ativas,clientes}','navigation','/painel/jornadas?status=active',null,'journeys:view','low','store',85),('pause-journey','Pausar jornada','Solicitar pausa controlada','{pausar,jornada}','operational_action',null,'PAUSE_CUSTOMER_JOURNEY','journeys:pause','high','store',86) on conflict(id) do nothing;

do $$ declare t text;begin foreach t in array array['journey_member_permissions','customer_journeys','customer_journey_versions','journey_entry_triggers','journey_entry_rules','journey_stages','journey_stage_edges','customer_journey_enrollments','journey_stage_events','journey_event_waits','journey_action_requests','journey_suppressions','journey_frequency_events','journey_experiments','journey_experiment_assignments','journey_conversions','journey_simulations','journey_templates','journey_jobs','journey_audit_events','fact_journey_enrollments','fact_journey_stage_transitions','fact_journey_actions','fact_journey_conversions','fact_journey_suppressions','fact_journey_experiments','dim_journey','dim_journey_stage','dim_journey_objective','dim_suppression_reason','dim_experiment_variant'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',left(t||'_service_only',63),t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
comment on table public.customer_journeys is 'Specialized customer journey definitions compiled to Automation Center; never a second generic executor.';comment on table public.journey_suppressions is 'Suppression is a protected outcome, not a failure.';comment on table public.journey_conversions is 'Attribution does not imply causality; incremental lift requires valid control evidence.';
notify pgrst,'reload schema';
